                            log.warn("Could not create an instance for " + "QueryProcessorFactoryIF service '" + line + "'.");
                        }
                    }
                } catch (IOException e) {
                    log.warn("Could not read from QueryProcessorFactoryIF " + "service descriptor.", e);
                }
            }
