            ret.setStderr("Can't unzip software bundle " + options.valueOf("input-file") + " to directory " + options.valueOf("output-dir"));
            ret.setExitStatus(ReturnValue.RUNTIMEEXCEPTION);
        }
        return (ret);
    }

