                                    }
                                }
                            }
                        }
                    }
                    FundView.write("EndOfMethod");
                    FundView.newLine();
                    foundRead = false;
                    foundWrite = false;
                }
                if (classWritten == true) {
                    FundView.write("EndOfClass");
                    FundView.newLine();
                    classWritten = false;
                }
            }
            PC.close();
            FundView.close();
