                return result;
            }

            public String getColumnText(Object object, int columnIndex) {
                String result = super.getText(object);
                if (object instanceof Diagram) {
                    if (editor.getDiagram() == object) {
                        result += " (active)";
                    }
                }
                return result;
            }
