                if (sourceChannel != null) {
                    sourceChannel.close();
                }
                if (targetChannel != null) {
                    targetChannel.close();
                }
            } catch (IOException e) {
                logger.warning("closing channels failed");
            }
        }
        return isBkupFileOK;
    }

