            File f = new File(fi.directory + fi.fileName);
            if (f == null || f.isDirectory()) return null; else {
                InputStream is = new FileInputStream(f);
                if (fi.compression >= FileInfo.LZW) is = new RandomAccessStream(is);
                return is;
            }
        }
    }

