            int size;
            while ((size = in.read(buffer, 0, buffer.length)) != -1) {
                if (this.isCancelled()) break;
                if (bos != null) bos.write(buffer, 0, size);
                if (size > 0) {
                    digest.update(buffer, 0, size);
                    this.length += size;
                    progress();
                }
            }
        } finally {
            if (bos != null) {
                bos.flush();
                bos.close();
            }
        }
        if (!cancelled) this.checkSum = CheckSum.toString(digest.digest());
    }

