                LOG.log(Level.SEVERE, "[Exception] Problem in " + getClass().getName(), e);
            }
            LOG.info("Done with async download of list of downloadable maps for " + getText() + "...");
            remove(isLoadingMenuItem);
            if (myTreeNode != null) {
                myTreeNode.doneLoading();
            }
        }

