        httpReq.setAttribute("dataSources", rfm.getDataSources());
        Long reportId = UtilMethods.parseLong(req.getParameter("reportId"), 0);
        String referrer = req.getParameter("referrer");
        if (reportId > 0) {
            report = ReportFactory.getReport(reportId);
