        Log.d(TAG, "Fetching stock data from Yahoo");
        ArrayList<Stock> newStocks = new ArrayList<Stock>(stocks.length);
        if (stocks.length > 0) {
            StringBuilder sb = new StringBuilder();
            for (Stock stock : stocks) {
                sb.append(stock.getSymbol());
                sb.append('+');
