                                    for (int i = 0; i < kr.length; i++) {
                                        if (i > 0) bw.write(" ");
                                        bw.write(kr[i].kanji);
                                        if (kr[i].type != KReading.KANA) {
                                            bw.write("|");
                                            bw.write(kr[i].reading);
                                        }
                                    }
                                } else {
                                    bw.write(word.original);
                                    bw.write("|");
                                    bw.write(word.reading);
                                }
                            } else {
                                bw.write(word.original);
                            }
                            bw.write(" // \r\n");
                        }
                        if (english != null) {
                            bw.write(english);
                            bw.write("\r\n");
                        }
                        bw.write("\r\n");
                    }
                }
                br.close();
                bw.close();
