public String upload(String urlString, ByteArrayOutputStream dataStream) {
        HttpURLConnection conn = null;
        DataOutputStream dos = null;
        String exsistingFileName = "blah.png";
        String lineEnd = "\r\n";
        String twoHyphens = "--";
