                    destinationParent.mkdirs();
                    BufferedInputStream is = new BufferedInputStream(zipFile.getInputStream(entry));
                    FileOutputStream fos = new FileOutputStream(destFile);
                    IOUtils.copyLarge(is, fos);
                    fos.flush();
                    IOUtils.closeQuietly(fos);
                }
            }
        }
        zipFile.close();
    }

