                        urlConnection.connect();
                        serverCode = urlConnection.getResponseCode();
                    } catch (MalformedURLException e) {
                        e.printStackTrace();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                    if (serverCode == 200) {
                        actual = new File("../attachments/" + projectName + "/" + key);
