            is = new FileInputStream(setupKson);
        }
        BufferedReader br = new BufferedReader(new InputStreamReader(is, "UTF-8"));
        List<String> lines = new ArrayList<String>();
        while (true) {
            String line = br.readLine();
            if (line == null) break;
            lines.add(line);
