                _md.update(data.getBytes());
                byte[] _digest = _md.digest();
                String _ds;
                _ds = toHexString(_digest, 0, _digest.length);
                result = _ds;
            } catch (NoSuchAlgorithmException e) {
                result = null;
            }
        }
        return result;
    }

