        String myFile = (request.getQueryString() == null) ? "empty" : PublicEncryptionFactory.digestString(parsedQueryString).replace('\\', '_').replace('/', '_');
        myFile = Config.getStringProperty("PATH_TO_TITLE_IMAGES") + myFile + ".png";
